import {saltPrepTasks,prepSteps,validPrepSequence,phTasks,phClass,validNeutralEquation} from './saltph-models.js?v=20261023-physicscomplete01';
import {showSaltPh} from './saltph-scenes.js?v=20261023-physicscomplete01';
const select=(id,label,options,value='')=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select>`;
export function mountSaltPhWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},ph=l.widget==='saltph-ph',t=(ph?phTasks:saltPrepTasks)[i],$=s=>root.querySelector(s);const fields=ph?['classification']:['step0','step1','step2','step3','step4','reason'];
root.innerHTML=`<p><b>Case ${i+1} / 3</b></p>`+(ph?`<p>Set the explorer to pH ${t}, classify this solution, and complete the acid–alkali neutralisation equation. Your equation stays saved between cases.</p><label class="field-label" for="phExplorer">pH explorer</label><input id="phExplorer" type="range" min="0" max="14" step="1" value="${a.ph??7}">`+select('classification','Classification',[['acidic','Acidic'],['neutral','Neutral'],['alkaline','Alkaline']],a.classification)+`<label class="field-label" for="neutralEquation">Ionic equation (ASCII or Unicode)</label><input class="lab-input" id="neutralEquation" type="text" autocomplete="off" spellcheck="false"><p class="micro-note">Use -> for an arrow, H+ and OH- for ions, H2O for water. State symbols are optional.</p>`:`<p>Prepare pure, dry ${t.salt} from ${t.acid.toLowerCase()} and ${t.solid}. Put the five stages in order.</p>`+fields.slice(0,5).map((k,j)=>select(k,'Stage '+(j+1),prepSteps.slice().sort((a,b)=>a[0].localeCompare(b[0])),a[k])).join('')+select('reason','Why add excess insoluble solid?',[['consume','Use up the acid'],['dissolve','Dissolve every last piece of solid'],['dry','Remove water from the solution']],a.reason))+`<button class="secondary" id="checkSaltPh">Check my explanation</button><button class="secondary" id="nextSaltPh">Next case →</button><p id="saltPhProgress">${w.passed.length} / 3 cases correct</p>`;
fields.forEach(k=>$('#'+k).onchange=e=>{a[k]=e.target.value;save();});
if(ph){$('#neutralEquation').value=w.equation||'';$('#neutralEquation').oninput=e=>{w.equation=e.target.value;save();};$('#phExplorer').oninput=e=>{a.ph=Number(e.target.value);save();showSaltPh('ph',a.ph);};showSaltPh('ph',a.ph??7,w.passed.includes(i));}else showSaltPh('salts',t,w.passed.includes(i));
$('#checkSaltPh').onclick=()=>{const ok=ph?(a.ph??7)===t&&a.classification===phClass(t)&&validNeutralEquation(w.equation||''):validPrepSequence(fields.slice(0,5).map(k=>a[k]))&&a.reason==='consume';if(!ok){feedback(ph?'Set the explorer to the stated pH. Below7 is acidic,7 neutral, above 7 alkaline. H⁺ and OH⁻ form water; balance atoms and charge.':'React with excess solid first, then remove solid by filtration. Concentrate the filtrate, cool to form crystals, then separate/dry them. Excess solid consumes the acid; filtration alone does not remove dissolved acid.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showSaltPh(ph?'ph':'salts',t,true);$('#saltPhProgress').textContent=w.passed.length+' / 3 cases correct';feedback('Correct. Your choices support the displayed explanation.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextSaltPh').onclick=()=>{w.task=(i+1)%3;save();mountSaltPhWidget(l,p,root,{save,done,feedback});};}
